  local splitter=require('scripts/actions/mobskills/glacier_splitter');local move,process,status,random=xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove,math.random;local params,damage,paralysis=nil,nil,nil;local mob={getWeaponDmg=function()return 77 end};local target={takeDamage=function(_,...)damage={...}end};xi.mobskills.mobPhysicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.PHYSICAL,damageType=xi.damageType.SLASHING}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.mobStatusEffectMove=function(...)paralysis={...}end;math.random=function(min,max)assert(min==30 and max==60);return 45 end;assert(splitter.onMobSkillCheck(target,mob,{})==0 and splitter.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==77 and params.numHits==1 and params.fTP[1]==2 and params.fTP[2]==2 and params.fTP[3]==2 and params.attackType==xi.attackType.PHYSICAL and params.damageType==xi.damageType.SLASHING and params.shadowBehavior==xi.mobskills.shadowBehavior.NUMSHADOWS_3 and damage==nil and paralysis==nil);xi.mobskills.processDamage=function()return true end;splitter.onMobWeaponSkill(mob,target,{},{})
